@dataclass
class ERLocationData:
    __location_id: ClassVar[int] = 7000000
    """The next location ID to use when creating location data."""

    name: str
    """The name of this location according to Archipelago.

    This needs to be unique within this world."""

    default_item_name: Optional[str]
    """The name of the item that appears by default in this location.

    If this is None, that indicates that this location is an "event" that's
    automatically considered accessed as soon as it's available. Events are used
    to indicate major game transitions that aren't otherwise gated by items so
    that progression balancing and item smoothing is more accurate for ER.
    """

    ap_code: Optional[int] = None
    """Archipelago's internal ID for this location (also known as its "address")."""
    
    region_value: int = 0
    """The relative value of items in this location's region.

    This is used to sort locations when placing items like the base game.
    """
    
    region_name: str = ""
    """The name of the region this location is in."""
    
    key: Optional[str] = None
    """The key used by the static randomizer"""
    
    targets: Tuple[str, ...] = ()
    """The physical item-lot/shop rows used by the static randomizer."""

    missable: Union[bool, Callable[['ERLocationData', EROptions], bool]] = False
    """Whether this location is possible to permanently lose access to.

    This is also used for items that are *technically* possible to get at any time, but are
    prohibitively difficult without blocking off other checks (items dropped by NPCs on death
    generally fall into this category).

    Missable locations are always marked as excluded, so they will never contain
    progression or useful items.
    """
    
    omit: Union[bool, Callable[['ERLocationData', EROptions], bool]] = False
    """Whether to not include this location in the multiworld at all."""
    
    randomize: Union[bool, Callable[['ERLocationData', EROptions], bool]] = True
    """Whether to allow this location to be randomized.

    Even if this is True, the location may still be unrandomized based on to the player's options.
    If it's False, though, the location will never be randomized."""
    
    exclusive: bool = False
    """Whether this location is an exclusive item, other items are missed."""

    dlc: bool = False
    """Whether this location is only accessible if the DLC is enabled."""
    
    tp_dlc: bool = False
    """Whether this location is only accessible if the TP DLC is enabled."""

    npc: bool = False
    """"""
    
    death: bool = False
    """Whether this item is contingent on killing an NPC."""
    
    hostile_npc: bool = False
    """Whether this location is dropped by a hostile NPC."""

    prominent: bool = False
    """Whether this is one of few particularly prominent places for items to appear.

    This is a small number of locations (boss drops and progression locations)
    intended to be set as priority locations for players who don't want a lot of
    mandatory checks.

    For bosses with multiple drops, only one should be marked prominent.
    """

    progression: bool = False
    """Whether this location normally contains an item that blocks forward progress."""
    
    disallow_duplicates: bool = False
    """Whether this location can't be duplicated for important_at_priority_only."""
    
    basin: bool = False
    """Whether this location is a basin."""
    
    seedtree: bool = False
    """Whether this location is a seedtree."""
    
    church: bool = False
    """Whether this location is a church."""

    boss: bool = False
    """Whether this location is a reward for defeating a main boss."""
    
    altboss: bool = False
    """Whether this location is a reward for defeating a altboss."""
    
    miscboss: bool = False
    """Whether this location is a reward for defeating a miscboss."""
    
    minidungeonboss: bool = False
    """Whether this location is a reward for defeating a minidungeonboss."""
    
    catacombboss: bool = False
    """Whether this location is a reward for defeating a catacombboss."""
    
    graveboss: bool = False
    """Whether this location is a reward for defeating a graveboss."""
    
    caveboss: bool = False
    """Whether this location is a reward for defeating a caveboss."""
    
    tunnelboss: bool = False
    """Whether this location is a reward for defeating a tunnelboss."""
    
    dragonboss: bool = False
    """Whether this location is a reward for defeating a dragonboss."""
    
    night: bool = False
    """Whether this location is night boss."""
    
    miniboss: bool = False
    """Whether this location is miniboss."""
    
    criticalpath: bool = False
    """This location will always be gotten."""
    
    remembrance: bool = False
    """Whether this location is a remembrance."""
    
    achievement: bool = False
    """Whether this location is a reward for defeating a achievement boss."""
    
    end: bool = False
    """Whether this location is the end of base game."""
    
    dlc_end: bool = False
    """Whether this location is the end of dlc."""
    
    incantations: bool = False
    """Whether this location is an incantation."""
    
    sorceries: bool = False
    """Whether this location is an sorcery."""
    
    cookbook: bool = False
    """Whether this location is a cookbook."""
    
    talisman: bool = False
    """Whether this location is a talisman."""
    
    enemytalisman: bool = False
    """Whether this location is a talisman dropped by an enemy NPC."""

    drop: bool = False
    """Whether this is an item dropped by a (non-boss) enemy."""

    shop: bool = False
    """Whether this location can appear in an NPC's shop."""
    
    progshop: bool = False
    """Whether this shop can have prog at it when used with important_at_priority_only."""
    
    raceshop: bool = False #idk what is
    """Whether this location can appear in an raceshop."""
    
    upgradeshop: bool = False
    """Whether this location of a upgrade bell bearing."""
    
    smithingbell: bool = False
    """Whether this location of a smithing stone bell bearing"""
    
    keyitem: bool = False # racemode
    """Whether this location is a key item."""
    
    nokey: bool = False # idk
    """Whether this location is nokey"""
    
    premium: bool = False # idk but its good shop items i think
    """Whether this location is premium"""

    conditional: bool = False
    """Whether this location is conditional on a progression item.

    This is used to track locations that won't become available until an unknown amount of time into
    the run, and as such shouldn't have "similar to the base game" items placed in them.
    """
    
    hidden: bool = False
    """Whether this location is particularly tricky to find.

    This is for players without an encyclopedic knowledge of ER who don't want to get stuck looking
    for an illusory wall or one random mob with a guaranteed drop.
    """
    
    dungeon: bool = False
    """Whether this locations is inside of a dungeon."""
    
    unsweepable: bool = False
    """Whether this locations is inside of a dungeon and cannot be picked up via sweep."""
    
    outoftheway: bool = False
    """Whether this location is might take a bit to get."""
    
    scarab: bool = False
    """Whether this location is dropped by a scarab."""
    
    map: bool = False
    """Whether this location is a map."""
    
    breakable: bool = False
    """Whether this location requires an enemy to break a object, or save quit break."""
    
    evergaol: bool = False
    """Whether this location is a evergaol."""
    
    rise: bool = False
    """Whether this location is a rise."""
    
    fortress: bool = False
    """Whether this location is in a fortress."""
    
    painting: bool = False
    """Whether this location is a painting."""
    
    chest: bool = False
    """Whether this location is a chest."""
    
    ambush: bool = False
    """Whether this location is a ambush."""
    
    blizzard: bool = False
    """The damn blizzard area in snowfield."""
    
    # DLC
    fragment: bool = False
    """Whether this location is a scadu fragment."""
    
    enemyfragment: bool = False
    """Whether this location is a scadu fragment dropped by an enemy."""
    
    revered: bool = False
    """Whether this location is a revered spirit ash."""
    
    enemyrevered: bool = False
    """Whether this location is a revered spirit ash dropped by an enemy."""
    
    cross: bool = False
    """Whether this location is an item at a cross."""
    
    furnacegolem: bool = False
    """Whether this location is a furnace golem."""
    
    hangingpot: bool = False
    """Whether this location is a hanging pot."""
    
    bluegraves: bool = False
    """Whether this location is a blue graves location, they only appear at night."""
    
    namelessmausoleum: bool = False
    """Whether this location is a nameless mausoleum."""
    
    gaolboss: bool = False
    """Whether this location is a gaolboss."""
    
    gaolkey: bool = False
    """Whether this location is a gaolkey."""
    
    forgereward: bool = False
    """Whether this location is a forgereward."""
    
    spiritspring_stone: bool = False
    """Whether this location is a spiritspring stone."""
    
    @property
    def is_event(self) -> bool:
        """Whether this location represents an event rather than a specific item pickup."""
        return self.default_item_name is None

    def __post_init__(self):
        if not self.is_event:
            self.ap_code = self.ap_code or ERLocationData.__location_id
            ERLocationData.__location_id += 1
        if self.enemyfragment: self.fragment = True
        if self.hangingpot: self.hidden = True
            
        if self.exclusive: # makes sure exclusive is marked missable
            self.missable = True

    def is_missable(self, options: EROptions) -> bool:
        """Whether this location is missable given a set of options."""
        return self.missable if isinstance(self.missable, bool) else self.missable(self, options)

    def should_omit(self, options: EROptions) -> bool:
        """Whether this location should be omitted given a set of options."""
        return (
            self.dlc and not options.enable_dlc.value
        ) or (
            self.tp_dlc and not options.enable_tp_dlc.value
        ) or (
            self.spiritspring_stone and not options.spiritspring_stones
        ) or (
            (self.omit if isinstance(self.omit, bool) else self.omit(self, options))
            and self.name not in all_boss_locations_dictionary
            and item_table[self.default_item_name].is_important(options) not in 
            (ItemClassification.progression, ItemClassification.progression_deprioritized)
        ) or (
            options.excluded_location_behavior.value == 4
            and self.name in options.exclude_locations.value
            and self.name not in all_boss_locations_dictionary
            and item_table[self.default_item_name].is_important(options) not in 
            (ItemClassification.progression, ItemClassification.progression_deprioritized)
        ) or (
            options.missable_location_behavior.value == 4 and self.is_missable(options)
            and self.name not in all_boss_locations_dictionary
            and item_table[self.default_item_name].is_important(options) not in 
            (ItemClassification.progression, ItemClassification.progression_deprioritized)
        )

    def should_randomize(self, options: EROptions) -> bool:
        """Whether this location should be forced to contain its default item."""
        if not ( # if randomize is False, return False else continue
            self.randomize if isinstance(self.randomize, bool)
            else self.randomize(self, options)
        ): return False
        
        return not (( # if any of these are true, return False
            options.missable_location_behavior.value >= 3
            and self.is_missable(options)
        ) or (
            options.excluded_location_behavior.value >= 3
            and self.name in options.exclude_locations.value
        ) or (self.default_item_name == "Crafting Kit" and options.crafting_kit_option.value == 2
        ) or (self.default_item_name == "Flask of Wondrous Physick" and options.physick_flask_option.value == 2
        ) or (self.map and options.map_option.value == 2
        ) or (self.smithingbell and options.smithing_bell_bearing_option.value == 2
        ) or (self.default_item_name == "Serpent-Hunter" and not options.enemy_rando and options.rykard_encounter
        ))

    def location_groups(self) -> List[str]:
        """The names of location groups this location should appear in.

        This is computed from the properties assigned to this location."""
        names = []
        if self.name in all_boss_locations_dictionary:
            if not self.dlc:
                names.append("Boss Reward")
            else:
                names.append("DLC Boss Reward")
        
        if self.achievement: names.append("Achievement Boss")      
        if self.remembrance and self.dlc: names.append("DLC Remembrance Boss")
        
        if self.keyitem and not self.missable: 
            if self.dlc:
                names.append("DLC Key Items")
            else:
                names.append("Key Items")
        if self.prominent: names.append("Prominent")
        if self.progression: names.append("Progression")
        if self.hostile_npc: names.append("Hostile NPC Rewards")
        if self.npc: names.append("Friendly NPC Rewards")
        if self.dungeon: names.append("Dungeon")
        if self.chest: 
            if self.dlc:
                names.append("DLC Chest")
            else:
                names.append("Chest")
        if self.scarab:
            if self.dlc:
                names.append("DLC Scarab")
            else:
                names.append("Scarab")
        if self.progshop: 
            if self.dlc:
                names.append("DLC Shop")
            else:
                names.append("Shop")
            self.disallow_duplicates = True
        if self.outoftheway: names.append("Out of the Way")
        if self.drop: names.append("Drop")
        if self.hidden: names.append("Hidden")
        if self.blizzard: names.append("Blizzard")
        if self.dlc: names.append("DLC")
        if self.furnacegolem: names.append("Furnace Golem")
        if self.map: 
            if self.dlc:
                names.append("DLC Map")
            else:
                names.append("Map")
        if self.church: names.append("Church")
        if self.cross: names.append("Cross")
        if self.seedtree: names.append("Seedtree")
        if self.basin: names.append("Basin")
        if self.fragment: names.append("Fragment")
        if self.revered: names.append("Revered")
        if self.spiritspring_stone: 
            names.append("Spiritspring Stones")
            self.disallow_duplicates = True
        
        if self.region_value >= len(region_order) - 21 and self.region_value <= len(region_order):
            names.append("Post Leyndell")
            
        if self.region_value > location_tables["Earthbore Cave"][0].region_value: # everything after weeping in region_order
            names.append("Post Stormveil")

        default_item = item_table[cast(str, self.default_item_name)]
        names.append({
                         ERItemCategory.GOODS: "Goods",
                         ERItemCategory.WEAPON: "Weapons",
                         ERItemCategory.ARMOR: "Armor",
                         ERItemCategory.ACCESSORY: "Accessory",
                         ERItemCategory.ASHOFWAR: "Ash of war",
                         #ERItemCategory.CUSTOMWEAPON: "Upgraded Weapons",
                     }[default_item.category])
        if default_item.classification == ItemClassification.progression:
            names.append("Progression")
            self.progression = True
            
        # testing
        names.append("All Locations")
        
        return names


class ERLocation(Location):
    game: str = "EldenRing"
    data: ERLocationData

    def __init__(
            self,
            player: int,
            data: ERLocationData,
            parent: Optional[Region] = None,
            event: bool = False):
        super().__init__(player, data.name, None if event else data.ap_code, parent)
        self.data = data

def disable_base(self: ERLocationData, options: EROptions) -> bool:
    """A utility function for locations that are omitted when Base is disabled."""
    return options.enable_dlc.value and options.dlc_start.value == 1

def disable_dlc(self: ERLocationData, options: EROptions) -> bool:
    """A utility function for locations that are omitted when DLC is disabled."""
    return not options.enable_dlc.value

def disable_tp_dlc(self: ERLocationData, options: EROptions) -> bool:
    """A utility function for locations that are omitted when TP DLC is disabled."""
    return not options.enable_tp_dlc.value

def missable_capital(self: ERLocationData, options: EROptions) -> bool:
    return not options.royal_access.value

# from ds3 locations.py

# * Avoid using vanilla enemy placements as landmarks, because these are
#   randomized by the enemizer by default. Instead, use generic terms like
#   "enemy", "boss", and "npc".

# * Location descriptions don't need to direct the player to the precise spot.
#   You can assume the player is broadly familiar with Eldenring or willing
#   to look at a vanilla guide. Just give a general area to look in or an idea
#   of what quest a check is connected to. Terseness is valuable: try to keep
#   each location description short enough that the whole line doesn't exceed
#   100 characters.

# * Use "[name] drop" for items that require killing an NPC who becomes hostile
#   as part of their normal quest, "kill [name]" for items that require killing
#   them even when they aren't hostile, and just "[name]" for items that are
#   naturally available as part of their quest.

# items that are always prominent, unless the check is missable or a boss drop
# golden seed, sacred tear, Imbued Sword Key and memory stone if not in a rise

# for descriptions 
# [area acronym]/[grace or location acronym]: [original item] - [what gives item, if it does] [direction from grace] or [very brief description]

# CD/AFCHN: Lifesteal Fist - scarab to NW         # grace             to DIR      
# LG/WR: Golden Rune [1] - graveyard S of WR      # location          DIR of location acro
# LG/(CE): Smithing Stone [1] - on anvil          # within location   (location acro) at start

# the rare hostile npc's that aren't red      # hostile npc drop
# invaders / red npc's                        # invader drop
# non boss enemies with a guaranteed drop     # enemy drop / ballon drop
# bosses                                      # boss drop / night boss drop

# NPC names are capitalized

# Catacomb = CC, Cave = CV, Coast = CO

# Tombsward Ruins, Tower of Return = TwR, ToR

# NR = Nokron, NS = Nokstella

# Evergaol example "CL/(SE): Battlemage Hugues - boss drop Evergaol"

# erdtree example "LL/EME: item - boss drop, Minor Erdtree"

# breakable statue example  "MtG/HS: Smithing Stone [6] x3 - breakable statue S of HS"
# and it needs a tag   breakable=True

# items that share an itemlot
#"MP/PALR|(MDM): Golden Seed - seedtree in S blood swamp AND SE of boss elevator behind statue down below on rocks, getting one and reloading area deletes the other"


